import { Component, inject, signal } from '@angular/core';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import {
  IconLayoutDashboard, IconFolder, IconChartBar, IconUsers, IconSettings,
  IconFileText, IconChevronRight, IconChevronDown, IconBell, IconBuilding,
  IconLayoutSidebarLeftCollapse, IconLayoutSidebarLeftExpand,
} from '@tabler/icons-angular';
import { TablerIconComponent } from '@tabler/icons-angular';
import { NzDropDownModule } from 'ng-zorro-antd/dropdown';
import { NzMenuModule } from 'ng-zorro-antd/menu';
import { HrmSideNav, HrmNavSection, HrmDropdown } from 'hrm-ui';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont, SgExample, SgRow } from '../../../doc/sg-blocks';

/** Doc page · Side Nav (Appshell). Tương tác thật: bấm mục đổi trang; chuông + tài khoản mở dropdown;
 *  khối user ở đáy (avatar/tên/email/cài đặt); thu gọn → mọi thứ về icon vuông. Song ngữ qua i18n docs.sideNav.*. */
@Component({
  selector: 'sg-doc-side-nav',
  imports: [TranslateModule, TablerIconComponent, NzDropDownModule, NzMenuModule, HrmSideNav, HrmDropdown, SgDoc, SgUse, SgDo, SgDont, SgExample, SgRow],
  template: `
    <sg-doc category="Appshell" [title]="'docs.sideNav.title' | translate" [desc]="'docs.sideNav.desc' | translate">

      <div sgOverview>
        <div style="width:max-content">
          <hrm-side-nav [sections]="overview" [selectedKey]="selOv()" (itemClick)="selOv.set($event.key)"
            [collapsed]="colOv()" (collapsedChange)="colOv.set($event)" [caretIcon]="caret"
            [logoSrc]="logoFull" [logoMarkSrc]="logoMark" [toggleIcon]="sbCollapse" [expandIcon]="sbExpand">
            <button snActions type="button" class="sn-bell" [attr.aria-label]="'docs.sideNav.ariaNotify' | translate" [hrmDropdown]="notifyMenu" hrmDropdownTrigger="click">
              <tabler-icon [icon]="bell" [size]="20" /><span class="sn-bell-dot"></span>
            </button>
            <button snFooter type="button" class="sn-user" [class.sn-user--mini]="colOv()" [hrmDropdown]="userMenu" hrmDropdownTrigger="click" [attr.aria-label]="'docs.sideNav.ariaAccount' | translate">
              <span class="sn-user-av">ĐV</span>
              @if (!colOv()) {
                <span class="sn-user-info">
                  <span class="sn-user-name">Đặng Vũ</span>
                  <span class="sn-user-mail">danganh&#64;vnr.vn</span>
                </span>
                <tabler-icon [icon]="settings" [size]="16" class="sn-user-gear" />
              }
            </button>
          </hrm-side-nav>
        </div>
        <p style="font-size: var(--fs-13);color:var(--text-sub);margin:12px 0 0;max-width:58ch;line-height:1.5" [innerHTML]="'docs.sideNav.ovNote' | translate"></p>
      </div>

      <div sgUsage>
        <sg-use
          [purpose]="'docs.sideNav.purpose' | translate"
          [when]="when"
          [behavior]="'docs.sideNav.behavior' | translate"
          [avoid]="'docs.sideNav.avoid' | translate" />
      </div>

      <div sgBest>
        <sg-do><span [innerHTML]="'docs.sideNav.do1' | translate"></span></sg-do>
        <sg-do><span [innerHTML]="'docs.sideNav.do2' | translate"></span></sg-do>
        <sg-dont>{{ 'docs.sideNav.dont1' | translate }}</sg-dont>
        <sg-dont>{{ 'docs.sideNav.dont2' | translate }}</sg-dont>
      </div>

      <div sgExamples>
        <sg-example [title]="'docs.sideNav.exEndT' | translate"
          [desc]="'docs.sideNav.exEndD' | translate">
          <sg-row>
            <div style="width:max-content">
              <hrm-side-nav [sections]="endContent" [selectedKey]="selEnd()" (itemClick)="selEnd.set($event.key)" [caretIcon]="caret"
                [logoSrc]="logoFull" [logoMarkSrc]="logoMark" [toggleIcon]="sbCollapse" [expandIcon]="sbExpand">
                <button snActions type="button" class="sn-bell" [attr.aria-label]="'docs.sideNav.ariaNotify' | translate" [hrmDropdown]="notifyMenu" hrmDropdownTrigger="click">
                  <tabler-icon [icon]="bell" [size]="20" /><span class="sn-bell-dot"></span>
                </button>
              </hrm-side-nav>
            </div>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.sideNav.exNestedT' | translate"
          [desc]="'docs.sideNav.exNestedD' | translate">
          <sg-row>
            <div style="width:max-content">
              <hrm-side-nav [sections]="nested" [selectedKey]="selNest()" (itemClick)="selNest.set($event.key)" [caretIcon]="caret"
                [logoSrc]="logoFull" [logoMarkSrc]="logoMark" [toggleIcon]="sbCollapse" [expandIcon]="sbExpand">
                <button snActions type="button" class="sn-bell" [attr.aria-label]="'docs.sideNav.ariaNotify' | translate" [hrmDropdown]="notifyMenu" hrmDropdownTrigger="click">
                  <tabler-icon [icon]="bell" [size]="20" /><span class="sn-bell-dot"></span>
                </button>
              </hrm-side-nav>
            </div>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.sideNav.exSwitchT' | translate"
          [desc]="'docs.sideNav.exSwitchD' | translate">
          <sg-row>
            <div style="width:max-content">
              <hrm-side-nav [sections]="headerNav" [selectedKey]="selHdr()" (itemClick)="selHdr.set($event.key)"
                [collapsed]="colHdr()" (collapsedChange)="colHdr.set($event)" [caretIcon]="caret"
                [logoSrc]="logoFull" [logoMarkSrc]="logoMark" [toggleIcon]="sbCollapse" [expandIcon]="sbExpand">
                <button snActions type="button" class="sn-bell" [attr.aria-label]="'docs.sideNav.ariaNotify' | translate" [hrmDropdown]="notifyMenu" hrmDropdownTrigger="click">
                  <tabler-icon [icon]="bell" [size]="20" /><span class="sn-bell-dot"></span>
                </button>
                <button snHead type="button" class="sn-acct" [class.sn-acct--mini]="colHdr()" [hrmDropdown]="acctMenu" hrmDropdownTrigger="click" [attr.aria-label]="'docs.sideNav.switchAccount' | translate">
                  <span class="sn-acct-ic"><tabler-icon [icon]="switcher" [size]="18" /></span>
                  @if (!colHdr()) {
                    <span style="flex:1;min-width:0">
                      <span style="display:block;font-size: var(--fs-14);font-weight:600;color:var(--text-strong)">{{ account().name }}</span>
                      <span style="display:block;font-size: var(--fs-12);color:var(--text-sub)">{{ account().sub }}</span>
                    </span>
                    <tabler-icon [icon]="chevDown" [size]="16" style="color:var(--text-soft)" />
                  }
                </button>
                <button snFooter type="button" class="sn-user" [class.sn-user--mini]="colHdr()" [hrmDropdown]="userMenu" hrmDropdownTrigger="click" [attr.aria-label]="'docs.sideNav.ariaAccount' | translate">
                  <span class="sn-user-av">ĐV</span>
                  @if (!colHdr()) {
                    <span class="sn-user-info">
                      <span class="sn-user-name">Đặng Vũ</span>
                      <span class="sn-user-mail">danganh&#64;vnr.vn</span>
                    </span>
                    <tabler-icon [icon]="settings" [size]="16" class="sn-user-gear" />
                  }
                </button>
              </hrm-side-nav>
            </div>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.sideNav.exSearchT' | translate"
          [desc]="'docs.sideNav.exSearchD' | translate">
          <sg-row>
            <div style="width:max-content">
              <hrm-side-nav [sections]="searchNav" [selectedKey]="selSrch()" (itemClick)="selSrch.set($event.key)" [caretIcon]="caret"
                [logoSrc]="logoFull" [logoMarkSrc]="logoMark" [toggleIcon]="sbCollapse" [expandIcon]="sbExpand"
                [searchable]="true" [searchPlaceholder]="'docs.sideNav.searchPh' | translate" [clearLabel]="'docs.sideNav.searchClear' | translate" [searchEmpty]="'docs.sideNav.searchEmpty' | translate">
                <button snActions type="button" class="sn-bell" [attr.aria-label]="'docs.sideNav.ariaNotify' | translate" [hrmDropdown]="notifyMenu" hrmDropdownTrigger="click">
                  <tabler-icon [icon]="bell" [size]="20" /><span class="sn-bell-dot"></span>
                </button>
              </hrm-side-nav>
            </div>
          </sg-row>
        </sg-example>
      </div>
    </sg-doc>

    <!-- Dropdown thông báo (dùng chung mọi chuông) -->
    <nz-dropdown-menu #notifyMenu="nzDropdownMenu">
      <ul nz-menu style="min-width:260px">
        <li nz-menu-item><span [innerHTML]="'docs.sideNav.notifyLeave' | translate"></span></li>
        <li nz-menu-item><span>{{ 'docs.sideNav.notifyPayroll' | translate }}</span></li>
        <li nz-menu-item><span>{{ 'docs.sideNav.notifyOnboard' | translate }}</span></li>
        <li nz-menu-divider></li>
        <li nz-menu-item style="color:var(--primary-base)">{{ 'docs.sideNav.notifyAll' | translate }}</li>
      </ul>
    </nz-dropdown-menu>

    <!-- Dropdown đổi tài khoản/tổ chức -->
    <nz-dropdown-menu #acctMenu="nzDropdownMenu">
      <ul nz-menu style="min-width:220px">
        <li nz-menu-item (click)="setAcct('Tập đoàn VNR', tr('acctEnterprise'))">Tập đoàn VNR</li>
        <li nz-menu-item (click)="setAcct(tr('acctHcm'), tr('acctSouth'))">{{ 'docs.sideNav.acctHcm' | translate }}</li>
        <li nz-menu-item (click)="setAcct(tr('acctHanoi'), tr('acctNorth'))">{{ 'docs.sideNav.acctHanoi' | translate }}</li>
      </ul>
    </nz-dropdown-menu>

    <!-- Dropdown tài khoản người dùng (đáy) -->
    <nz-dropdown-menu #userMenu="nzDropdownMenu">
      <ul nz-menu style="min-width:200px">
        <li nz-menu-item>{{ 'docs.sideNav.userProfile' | translate }}</li>
        <li nz-menu-item>{{ 'docs.sideNav.userSettings' | translate }}</li>
        <li nz-menu-divider></li>
        <li nz-menu-item style="color:var(--error-base)">{{ 'docs.sideNav.userLogout' | translate }}</li>
      </ul>
    </nz-dropdown-menu>
  `,
  styles: [`
    .sn-bell { position: relative; display: grid; place-items: center; width: 34px; height: 34px; border: 0; background: transparent; border-radius: var(--radius-md); cursor: pointer; color: var(--text-sub); transition: background var(--duration-fast, .15s) var(--ease-out, ease), color var(--duration-fast, .15s) var(--ease-out, ease); }
    .sn-bell:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }
    .sn-bell-dot { position: absolute; top: 7px; right: 8px; width: 7px; height: 7px; border-radius: 50%; background: var(--error-base); border: 1.5px solid var(--bg-surface); }

    .sn-acct { display: flex; align-items: center; gap: 10px; width: 100%; padding: 8px; border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface); cursor: pointer; text-align: left; transition: border-color var(--duration-fast, .15s) var(--ease-out, ease); }
    .sn-acct:hover { border-color: var(--primary-base); }
    .sn-acct--mini { width: auto; padding: 4px; border-color: transparent; background: transparent; }
    .sn-acct-ic { display: grid; place-items: center; width: 32px; height: 32px; border-radius: var(--radius-md); background: var(--primary-bg-subtle); color: var(--primary-base); flex: none; }

    .sn-user { display: flex; align-items: center; gap: 10px; width: 100%; padding: 6px 8px; border: 0; background: transparent; border-radius: var(--radius-lg); cursor: pointer; text-align: left; transition: background var(--duration-fast, .15s) var(--ease-out, ease); }
    .sn-user:hover { background: var(--bg-surface-subtle); }
    .sn-user--mini { width: auto; padding: 4px; }
    .sn-user-av { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; background: var(--primary-base); color: #fff; font-size: var(--fs-13); font-weight: 600; flex: none; }
    .sn-user-info { flex: 1; min-width: 0; }
    .sn-user-name { display: block; font-size: var(--fs-14); font-weight: 600; color: var(--text-strong); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .sn-user-mail { display: block; font-size: var(--fs-12); color: var(--text-sub); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .sn-user-gear { color: var(--text-soft); flex: none; }
  `],
})
export class SgDocSideNav {
  private readonly t = inject(TranslateService);
  protected tr(key: string): string { return this.t.instant('docs.sideNav.' + key); }

  protected readonly caret = IconChevronRight;
  protected readonly chevDown = IconChevronDown;
  protected readonly sbCollapse = IconLayoutSidebarLeftCollapse;
  protected readonly sbExpand = IconLayoutSidebarLeftExpand;
  protected readonly bell = IconBell;
  protected readonly switcher = IconBuilding;
  protected readonly settings = IconSettings;
  protected readonly logoFull = '/assets/vnr-logo-full.svg';
  protected readonly logoMark = '/assets/vnr-logo-mark.svg';

  protected readonly selOv = signal('dash');
  protected readonly selEnd = signal('dash');
  protected readonly selNest = signal('general');
  protected readonly selHdr = signal('dash');
  protected readonly colOv = signal(false);
  protected readonly colHdr = signal(false);
  protected readonly account = signal({ name: 'Tập đoàn VNR', sub: this.tr('acctEnterprise') });
  protected setAcct(name: string, sub: string): void { this.account.set({ name, sub }); }

  protected get overview(): HrmNavSection[] {
    return [
      { header: this.tr('secMain'), items: [
        { key: 'dash', label: this.tr('itemDashboard'), icon: IconLayoutDashboard },
        { key: 'proj', label: this.tr('itemProject'), icon: IconFolder },
        { key: 'ana', label: this.tr('itemAnalytics'), icon: IconChartBar },
      ] },
      { header: this.tr('secDocs'), items: [
        { key: 'docs', label: this.tr('itemAllDocs'), icon: IconFileText },
      ] },
    ];
  }

  protected get endContent(): HrmNavSection[] {
    return [
      { header: this.tr('secMain'), items: [
        { key: 'dash', label: this.tr('itemDashboard'), icon: IconLayoutDashboard },
        { key: 'proj', label: this.tr('itemProject'), icon: IconFolder, badge: 12 },
        { key: 'ana', label: this.tr('itemAnalytics'), icon: IconChartBar, badge: this.tr('badgeNew') },
        { key: 'team', label: this.tr('itemTeam'), icon: IconUsers, trailing: this.tr('trailingMembers') },
      ] },
    ];
  }

  protected get nested(): HrmNavSection[] {
    return [
      { header: this.tr('secMain'), items: [
        { key: 'dash', label: this.tr('itemDashboard'), icon: IconLayoutDashboard },
        { key: 'set', label: this.tr('itemSettings'), icon: IconSettings, children: [
          { key: 'general', label: this.tr('itemGeneral') },
          { key: 'security', label: this.tr('itemSecurity') },
          { key: 'notify', label: this.tr('itemNotify') },
        ] },
      ] },
    ];
  }

  protected get headerNav(): HrmNavSection[] {
    return [
      { header: this.tr('secNavigation'), items: [
        { key: 'dash', label: this.tr('itemDashboard'), icon: IconLayoutDashboard },
        { key: 'set', label: this.tr('itemSettings'), icon: IconSettings },
      ] },
    ];
  }

  protected readonly selSrch = signal('emp');
  protected get searchNav(): HrmNavSection[] {
    return [
      { items: [
        { key: 'nhansu', label: this.tr('grpStaff'), icon: IconUsers, keywords: this.kw('kwStaff'), children: [
          { key: 'emp', label: this.tr('itemStaffList') },
          { key: 'org', label: this.tr('itemOrgChart') },
          { key: 'contract', label: this.tr('itemContract') },
        ] },
        { key: 'chamcong', label: this.tr('grpAttendance'), icon: IconChartBar, keywords: this.kw('kwAttendance'), children: [
          { key: 'timesheet', label: this.tr('itemTimesheet') },
          { key: 'leave', label: this.tr('itemLeave') },
          { key: 'shift', label: this.tr('itemShift') },
        ] },
        { key: 'luong', label: this.tr('grpPayroll'), icon: IconFileText, keywords: this.kw('kwPayroll'), children: [
          { key: 'payslip', label: this.tr('itemPayslip') },
          { key: 'tax', label: this.tr('itemTax') },
        ] },
      ] },
    ];
  }
  private kw(key: string): string[] {
    return this.tr(key).split('|').map(s => s.trim()).filter(Boolean);
  }

  protected readonly when = [
    'docs.sideNav.when1',
    'docs.sideNav.when2',
    'docs.sideNav.when3',
  ];
}
